const getCreatureHeadBaseMeta = (id: string) => {
  if (id.startsWith('ch_eye_')) return creatureHeadGroupMeta.eye;
  if (id.startsWith('ch_mou_')) return creatureHeadGroupMeta.mouth;
  if (id.startsWith('ch_hor_')) return creatureHeadGroupMeta.horn;
  if (id.startsWith('ch_str_')) return creatureHeadGroupMeta.structure;
  if (id.startsWith('ch_cyb_')) return creatureHeadGroupMeta.cyber;
  if (id.startsWith('ch_eld_')) return creatureHeadGroupMeta.eldritch;
  return creatureHeadGroupMeta.elemental;
};

const parseCreatureHeadName = (name: string) => {
  const zh = name.replace(/\s*\(.*/, '').trim();
  const detail = name.match(/\((.*?)\)/)?.[1]?.trim() || zh;
  return { zh, detail };
};

const creatureHeadRoleLabel: Record<NonNullable<LibraryItemDef['creaturePartRole']>, string> = {
  primary_head: '头部主结构',
  cranial_structure: '颅骨/头型结构',
  eye: '眼部结构',
  mouth: '口器/颚部结构',
  horn: '角冠/触须结构',
  head_tech: '头部机械接口',
  eldritch_head: '不可名状头部',
  elemental_head: '元素头部',
  torso: '躯干结构',
  limb: '肢体结构',
  lower_body: '下半身结构',
  wing: '翼部结构',
  tail: '尾部结构',
  internal_mutation: '内部异变结构',
  body_tech: '身体机械接口'
};

const creatureHeadModeText: Record<NonNullable<LibraryItemDef['creaturePartMode']>, string> = {
  replace: '作为头部主方案或整体替换使用，随机时应避免再叠加另一个整体头。',
  attach: '作为头部局部附着、器官或轮廓细节使用，可以服务于一个既定生物原型。',
  surface: '作为局部覆盖、表层异常或头面证据使用，不单独决定整个头型。',
  effect: '作为局部异常效果或视觉事件使用，适合增强识别点而不是替换本体。'
};

const describeCreatureHeadItem = (item: LibraryItemDef, meta: CreaturePartMeta) => {
  const { zh, detail } = parseCreatureHeadName(item.name);
  const role = creatureHeadRoleLabel[meta.creaturePartRole];
  const mode = creatureHeadModeText[meta.creaturePartMode];
  return {
    def: `${zh}：${role}。具体形态以“${detail}”为准，画面上要让${zh}成为可见的头部识别证据。${mode}`,
    defEn: `${zh}: ${role}. Use "${detail}" as the concrete visual form; it should read as visible head evidence. ${mode}`
  };
};

const withCreatureHeadMeta = (item: LibraryItemDef): LibraryItemDef => {
  const base = getCreatureHeadBaseMeta(item.id);
  const override = creatureHeadIdMeta[item.id] || {};
  const mergedMeta = { ...base, ...override };
  const itemDef = describeCreatureHeadItem(item, mergedMeta);
  return {
    ...item,
    ...base,
    ...itemDef,
    ...override,
    def: override.def || item.def || itemDef.def,
    defEn: override.defEn || item.defEn || itemDef.defEn,
    realityTags: [...new Set([...(base.realityTags || []), ...(override.realityTags || [])])],
    creatureFamilyAllow: [...new Set([...(base.creatureFamilyAllow || []), ...(override.creatureFamilyAllow || [])])],
    creatureFamilyFusion: [...new Set([...(base.creatureFamilyFusion || []), ...(override.creatureFamilyFusion || [])])],
    creatureFamilyBlock: [...new Set([...(base.creatureFamilyBlock || []), ...(override.creatureFamilyBlock || [])])],
    creatureTaxonomyFit: creatureHeadTaxonomyFit[item.id]
  };
};

