const withCreatureBodyMeta = (item: LibraryItemDef): LibraryItemDef => {
  const base = getCreatureBodyBaseMeta(item.id);
  const family = `body_${item.id.replace(/^cb_/, '')}`;
  return {
    ...base,
    ...item,
    def: item.def || base.def,
    defEn: item.defEn || base.defEn,
    realityTags: [...new Set([...(base.realityTags || []), ...(item.realityTags || [])])],
    creatureFamily: item.creatureFamily || family,
    creatureFamilyAllow: [...new Set([family, ...(base.creatureFamilyAllow || []), ...(item.creatureFamilyAllow || [])])],
    creatureFamilyFusion: [...new Set([...(base.creatureFamilyFusion || []), ...(item.creatureFamilyFusion || [])])],
    creatureFamilyBlock: [...new Set([...(base.creatureFamilyBlock || []), ...(item.creatureFamilyBlock || [])])],
    creatureTaxonomyFit: creatureBodyTaxonomyFit[item.id]
  };
};

